class Solution {
    pair<int, vector<int>> bfs(int start, const vector<vector<int>>& g) {
        vector<int> dist(g.size(), -1);
        queue<int> q;
        q.push(start);
        dist[start] = 0;
        int far = start;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            if (dist[u] > dist[far]) far = u;
            for (int v : g[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    q.push(v);
                }
            }
        }
        return {far, dist};
    }
public:
    string findSpecialNodes(int n, vector<vector<int>>& edges) {
        vector<vector<int>> g(n);
        for (const auto& e : edges) {
            g[e[0]].push_back(e[1]);
            g[e[1]].push_back(e[0]);
        }
        int a = bfs(0, g).first;
        auto fromA = bfs(a, g);
        auto fromB = bfs(fromA.first, g);
        int diameter = fromA.second[fromA.first];
        string ans(n, '0');
        for (int i = 0; i < n; ++i)
            if (max(fromA.second[i], fromB.second[i]) == diameter) ans[i] = '1';
        return ans;
    }
};
